SELECT 
FROM comments c JOIN users u ON u.id = c.user_id
WHERE c.id = #{id}

SELECT 
FROM comments c JOIN users u ON u.id = c.user_id
WHERE c.post_id = #{postId}
AND c.id < #{cursor}
ORDER BY c.id DESC
LIMIT #{limit}

SELECT post_id, count(*) AS count FROM comments WHERE post_id IN
#{postId}
GROUP BY post_id
